import { mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { generateApprovedGlyphs } from "./icon-generator";

const PKG_ROOT = path.resolve(import.meta.dirname, "..");
const OUT_FILE = path.join(PKG_ROOT, "src/generated/glyphs.ts");

function run(): void {
  const glyphs = generateApprovedGlyphs();
  const entries = Object.entries(glyphs);
  const lines: string[] = [
    "// Generated by packages/icons/scripts/build-icons.ts from packages/icons/src/manifest.ts.",
    "// Do not edit by hand; update src/manifest.ts and re-run `bun run generate`.",
    'import type { FileIconGlyphName } from "../manifest";',
    "",
    "export interface FileIconGlyph {",
    "  readonly viewBox: string;",
    "  readonly paths: string;",
    "}",
    "",
    "export const FILE_ICON_GLYPHS: Readonly<Record<FileIconGlyphName, FileIconGlyph>> = {",
  ];

  for (const [name, glyph] of entries) {
    lines.push(
      `  ${JSON.stringify(name)}: { viewBox: ${JSON.stringify(glyph.viewBox)}, paths: ${JSON.stringify(glyph.paths)} },`,
    );
  }
  lines.push("};", "");

  mkdirSync(path.dirname(OUT_FILE), { recursive: true });
  writeFileSync(OUT_FILE, lines.join("\n"));
  console.log(`build-icons: generated and validated ${entries.length} approved MIT/CC0 glyphs`);
}

run();
